"use client";
import { useEffect, useState } from "react";
import DATA from "../../../labs/charts/tokens/data.json";

/**
 * How text becomes tokens: the same sentences through four real tokenisers,
 * every chip one token exactly as the tokeniser returned it (generated by
 * scripts/labs/tokens.py; nothing is tokenised in the browser). A chip in
 * hex is a token that is only part of a character. Then strawberry, which
 * is the reason a model cannot see its own letters.
 */
type Tok = [number, string | null, string?];
type Kind = "cl100k" | "o200k" | "llama3" | "gemma3";
const TOKS = DATA.tokenizers as { id: Kind; name: string; who: string; vocab: number }[];
const SAMPLES = DATA.samples as unknown as { id: string; label: string; text: string; tokens: Record<Kind, Tok[]> }[];
const STRAWBERRY = DATA.strawberry as unknown as { text: string; tokens: Record<Kind, Tok[]> }[];

const WHY: Record<string, string> = {
  fox: "Common English is cheap: almost every word is one token, and the space before a word belongs to it. All four agree.",
  strawberry: "The question is eight or nine tokens and ' strawberry', with its space, is one of them. The model is asked about letters inside a token it receives as a single number.",
  code: "Code splits on punctuation. The GPT and Llama tokenisers have '.reduce' and '.price' as single pieces, learnt from all the JavaScript they were trained on; Gemma splits the dot off each.",
  numbers: "The GPT and Llama tokenisers group digits in threes from the left, so 2026 is 202 and 6, and 48213 is 482 and 13. Gemma 3 gives every digit its own token. Arithmetic on numbers chopped like this is harder than it looks.",
  japanese: "Seven characters, 21 bytes in UTF-8. GPT-4's tokeniser has few Japanese pieces, so it falls back to raw bytes, and 綺 and 麗 each become three tokens that are not characters at all. GPT-4o's larger vocabulary halves it; Gemma's 262,000 pieces get it to four.",
  emoji: "The moon emoji is four bytes and three tokens in cl100k: a model can emit the first byte of an emoji and not the rest. Gemma has the emoji as one piece.",
  welsh: "A long word that is rare in the training data is spelled out in fragments. The same is true of names, product names and most words in most languages that are not English.",
  indent: "Whitespace is tokens too, and each tokeniser cuts it differently. The GPT and Llama tokenisers glue the newline to the brace and lend the fourth space of the indent to ' return'; Gemma keeps the newline and all four spaces as tokens of their own.",
};

function show(t: string) {
  const out: (string | JSX.Element)[] = [];
  let buf = "";
  const flush = () => { if (buf) { out.push(buf); buf = ""; } };
  Array.from(t).forEach((ch, i) => {
    if (ch === " " || ch === "\n" || ch === "\t") { flush(); out.push(<span key={i} className="tk-ws" aria-hidden="true">{ch === " " ? "·" : ch === "\n" ? "↵" : "→"}</span>); }
    else buf += ch;
  });
  flush();
  return out;
}
const label = (t: Tok) => (t[1] === null ? `bytes ${t[2]}` : JSON.stringify(t[1]));

function Chips({ toks, onPick, picked }: { toks: Tok[]; onPick?: (t: Tok | null) => void; picked?: Tok | null }) {
  return (
    <ol className="tk-chips" aria-label={`${toks.length} tokens`}>
      {toks.map((t, i) => (
        <li key={i} className={`tk-chip h${i % 5}${t[1] === null ? " is-bytes" : ""}${picked === t ? " is-on" : ""}`} title={`id ${t[0]} · ${label(t)}`} tabIndex={onPick ? 0 : undefined} onMouseEnter={() => onPick?.(t)} onFocus={() => onPick?.(t)} aria-label={`token ${t[0]}: ${label(t)}`}>
          {t[1] === null ? <span className="tk-hex">{t[2]}</span> : show(t[1])}
        </li>
      ))}
    </ol>
  );
}

export function Tokens() {
  const [sid, setSid] = useState(SAMPLES[1].id);
  const [picked, setPicked] = useState<Tok | null>(null);
  useEffect(() => { const f = new URLSearchParams(window.location.search).get("focus"); if (f && SAMPLES.some((s) => s.id === f)) setSid(f); }, []);
  const s = SAMPLES.find((x) => x.id === sid)!;
  const chars = Array.from(s.text).length;
  const straw = STRAWBERRY[0];

  return (
    <div className="kp tk">
      <div className="un-samples" role="group" aria-label="Sentence">
        {SAMPLES.map((x) => <button key={x.id} type="button" className={`bo-toggle-btn ${x.id === sid ? "is-on" : ""}`} aria-pressed={x.id === sid} onClick={() => { setSid(x.id); setPicked(null); }}>{x.label}</button>)}
      </div>
      <p className="tk-text"><span className="tk-q">{s.text}</span> <small>{chars} characters · {new TextEncoder().encode(s.text).length} bytes</small></p>
      <p className="jd-note">{WHY[s.id]}</p>
      <div className="tk-rows">
        {TOKS.map((t) => (
          <section key={t.id} className="tk-row" aria-label={`${t.name}: ${s.tokens[t.id].length} tokens`}>
            <header className="tk-row-head">
              <b>{t.name}</b>
              <small>{t.who} · {t.vocab.toLocaleString("en-GB")} token ids</small>
              <span className="tk-count"><strong>{s.tokens[t.id].length}</strong> tokens</span>
            </header>
            <Chips toks={s.tokens[t.id]} onPick={setPicked} picked={picked} />
          </section>
        ))}
      </div>
      <p className="tk-readout" aria-live="polite">
        {picked ? <>Token <code>{picked[0]}</code> is {picked[1] === null ? <>the bytes <code>{picked[2]}</code>: part of a character, not a character</> : <><code>{JSON.stringify(picked[1])}</code>, {new TextEncoder().encode(picked[1]).length} bytes</>}. The model receives the number, never the text.</> : <>Hover a chip for its id. <span className="tk-ws">·</span> is a space, <span className="tk-ws">↵</span> a newline; a chip in hex is a token that is only part of a character.</>}
      </p>
      <p className="tk-ids"><span className="kp-knob-label">What GPT-4o actually receives</span><code>[{s.tokens.o200k.map((t) => t[0]).join(", ")}]</code></p>

      <h3 className="ct-h">Why it cannot count the r&rsquo;s in strawberry</h3>
      <p className="jd-note">To GPT-4o, <b>strawberry</b> is <code>[{straw.tokens.o200k.map((t) => t[0]).join(", ")}]</code>: {straw.tokens.o200k.map((t) => `“${t[1]}”`).join(", ")}. None of those is the letter r. Gemma 3 has the whole word as one piece, which hides the letters completely. Whatever a model knows about how its pieces are spelt, it had to learn as a fact about numbers: it cannot look. Spell the word out with spaces and every letter becomes its own token, and the count is suddenly easy.</p>
      <div className="tk-straw-wrap">
        <table className="jc-table tk-straw">
          <thead><tr><th>Input</th>{TOKS.map((t) => <th key={t.id}>{t.name}</th>)}</tr></thead>
          <tbody>
            {STRAWBERRY.map((w) => (
              <tr key={w.text}>
                <th scope="row"><code className="tk-in">{show(w.text)}</code></th>
                {TOKS.map((t) => <td key={t.id}><Chips toks={w.tokens[t.id]} /></td>)}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
